import{_ as l,a0 as o,w as d,s as r,I as n,x as a,a1 as i,A as p,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在執行一個命令或程序之前就瞭解它會做什麼 | LCTT x X-CMD","titleTemplate":false,"description":"如何在執行一個命令或程序之前就瞭解它會做什麼 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在執行一個命令或程序之前就瞭解它會做什麼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在執行一個命令或程序之前就瞭解它會做什麼 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171204 How To Know What A Command Or Program Will Exactly Do Before Executing It","title":"如何在執行一個命令或程序之前就瞭解它會做什麼","tag":"201712","desc":""},"relativePath":"201712/20171204 How To Know What A Command Or Program Will Exactly Do Before Executing It.md","filePath":"[post].md"}'),h={name:"201712/20171204 How To Know What A Command Or Program Will Exactly Do Before Executing It.md"};function u(g,s,m,c,b,k){const e=o("Link");return d(),r("div",null,[s[22]||(s[22]=n("h1",{id:"如何在執行一個命令或程序之前就瞭解它會做什麼",tabindex:"-1"},[a("如何在執行一個命令或程序之前就瞭解它會做什麼 "),n("a",{class:"header-anchor",href:"#如何在執行一個命令或程序之前就瞭解它會做什麼","aria-label":"Permalink to “如何在執行一個命令或程序之前就瞭解它會做什麼”"},"​")],-1)),n("p",null,[s[1]||(s[1]=a("有沒有想過在執行一個 Unix 命令前就知道它幹些什麼呢？並不是每個人都會知道一個特定的命令或者程序將會做什麼。當然，你可以用 ",-1)),i(e,{href:"https://www.ostechnix.com/explainshell-find-part-linux-command/"},{default:p(()=>[...s[0]||(s[0]=[a("Explainshell",-1)])]),_:1}),s[2]||(s[2]=a(" 來查看它。你可以在 Explainshell 網站中粘貼你的命令，然後它可以讓你瞭解命令的每個部分做了什麼。但是，這是沒有必要的。現在，我們從終端就可以輕易地在執行一個命令或者程序前就知道它會做什麼。 ",-1)),s[3]||(s[3]=n("code",null,"maybe",-1)),s[4]||(s[4]=a(" ，一個簡單的工具，它允許你運行一條命令並可以查看此命令對你的文件做了什麼，而實際上這條命令卻並未執行！在查看 ",-1)),s[5]||(s[5]=n("code",null,"maybe",-1)),s[6]||(s[6]=a(" 的輸出列表後，你可以決定是否真的想要運行這條命令。",-1))]),s[23]||(s[23]=t(`<p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/maybe-2-720x340.png" alt=""></p><h3 id="maybe-是如何工作的" tabindex="-1"><code>maybe</code> 是如何工作的 <a class="header-anchor" href="#maybe-是如何工作的" aria-label="Permalink to “maybe 是如何工作的”">​</a></h3><p>根據開發者的介紹：</p><blockquote><p><code>maybe</code> 利用 <code>python-ptrace</code> 庫在 <code>ptrace</code> 控制下運行了一個進程。當它截取到一個即將更改文件系統的系統調用時，它會記錄該調用，然後修改 CPU 寄存器，將這個調用重定向到一個無效的系統調用 ID（效果上將其變成一個無效操作（no-op）），並將這個無效操作（no-op）的返回值設置為有效操作的返回值。結果，這個進程認為，它所做的一切都發生了，實際上什麼都沒有改變。</p></blockquote><p>警告：在生產環境或者任何你所關心的系統裏面使用這個工具時都應該小心。它仍然可能造成嚴重的損失，因為它只能阻止少數系統調用。</p><h4 id="安裝-maybe" tabindex="-1">安裝 <code>maybe</code> <a class="header-anchor" href="#安裝-maybe" aria-label="Permalink to “安裝 maybe”">​</a></h4><p>確保你已經在你的 Linux 系統中已經安裝了 <code>pip</code> 。如果沒有，可以根據您使用的發行版，按照如下指示進行安裝。</p><p>在 Arch Linux 及其衍生產品（如 Antergos、Manjaro Linux）上，使用以下命令安裝 <code>pip</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S python-pip</span></span></code></pre></div><p>在 RHEL，CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install epel-release</span></span>
<span class="line"><span>sudo yum install python-pip</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install epel-release</span></span>
<span class="line"><span>sudo dnf install python-pip</span></span></code></pre></div><p>在 Debian，Ubuntu，Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install python-pip</span></span></code></pre></div><p>在 SUSE、 openSUSE 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zypper install python-pip</span></span></code></pre></div><p>安裝 <code>pip</code> 後，運行以下命令安裝 <code>maybe</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pip install maybe</span></span></code></pre></div><h3 id="瞭解一個命令或程序在執行前會做什麼" tabindex="-1">瞭解一個命令或程序在執行前會做什麼 <a class="header-anchor" href="#瞭解一個命令或程序在執行前會做什麼" aria-label="Permalink to “瞭解一個命令或程序在執行前會做什麼”">​</a></h3><p>用法是非常簡單的！只要在要執行的命令前加上 <code>maybe</code> 即可。</p><p>讓我給你看一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ maybe rm -r ostechnix/</span></span></code></pre></div><p>如你所看到的，我從我的系統中刪除一個名為 <code>ostechnix</code> 的文件夾。下面是示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>maybe has prevented rm -r ostechnix/ from performing 5 file system operations:</span></span>
<span class="line"><span></span></span>
<span class="line"><span> delete /home/sk/inboxer-0.4.0-x86_64.AppImage</span></span>
<span class="line"><span> delete /home/sk/Docker.pdf</span></span>
<span class="line"><span> delete /home/sk/Idhayathai Oru Nodi.mp3</span></span>
<span class="line"><span> delete /home/sk/dThmLbB334_1398236878432.jpg</span></span>
<span class="line"><span> delete /home/sk/ostechnix</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do you want to rerun rm -r ostechnix/ and permit these operations? [y/N] y</span></span></code></pre></div>`,25)),n("p",null,[i(e,{href:"http://www.ostechnix.com/wp-content/uploads/2017/12/maybe-1.png"},{default:p(()=>[...s[7]||(s[7]=[n("img",{src:"http://www.ostechnix.com/wp-content/uploads/2017/12/maybe-1.png",alt:""},null,-1)])]),_:1})]),s[24]||(s[24]=t(`<p><code>maybe</code> 執行了 5 個文件系統操作，並向我顯示該命令（<code>rm -r ostechnix/</code>）究竟會做什麼。現在我可以決定是否應該執行這個操作。是不是很酷呢？確實很酷！</p><p>這是另一個例子。我要為 Gmail 安裝 Inboxer 桌面客户端。這是我得到的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ maybe ./inboxer-0.4.0-x86_64.AppImage </span></span>
<span class="line"><span>fuse: bad mount point \`/tmp/.mount_inboxemDzuGV&#39;: No such file or directory</span></span>
<span class="line"><span>squashfuse 0.1.100 (c) 2012 Dave Vasilevsky</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: /home/sk/Downloads/inboxer-0.4.0-x86_64.AppImage [options] ARCHIVE MOUNTPOINT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FUSE options:</span></span>
<span class="line"><span> -d -o debug enable debug output (implies -f)</span></span>
<span class="line"><span> -f foreground operation</span></span>
<span class="line"><span> -s disable multi-threaded operation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>open dir error: No such file or directory</span></span>
<span class="line"><span>maybe has prevented ./inboxer-0.4.0-x86_64.AppImage from performing 1 file system operations:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>create directory /tmp/.mount_inboxemDzuGV</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do you want to rerun ./inboxer-0.4.0-x86_64.AppImage and permit these operations? [y/N]</span></span></code></pre></div><p>如果它沒有檢測到任何文件系統操作，那麼它會只顯示如下所示的結果。</p><p>例如，我運行下面這條命令來更新我的 Arch Linux。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ maybe sudo pacman -Syu</span></span>
<span class="line"><span>sudo: effective uid is not 0, is /usr/bin/sudo on a file system with the &#39;nosuid&#39; option set or an NFS file system without root privileges?</span></span>
<span class="line"><span>maybe has not detected any file system operations from sudo pacman -Syu.</span></span></code></pre></div><p>看到沒？它沒有檢測到任何文件系統操作，所以沒有任何警告。這非常棒，而且正是我所預料到的結果。從現在開始，我甚至可以在執行之前知道一個命令或一個程序將執行什麼操作。我希望這對你也會有幫助。</p><p>Cheers!</p><p>資源：</p>`,9)),n("ul",null,[n("li",null,[i(e,{href:"https://github.com/p-e-w/maybe"},{default:p(()=>[...s[8]||(s[8]=[n("code",null,"maybe",-1),a(" GitHub 主頁",-1)])]),_:1})])]),s[25]||(s[25]=n("hr",null,null,-1)),n("p",null,[s[10]||(s[10]=a("via: ",-1)),i(e,{href:"https://www.ostechnix.com/know-command-program-will-exactly-executing/"},{default:p(()=>[...s[9]||(s[9]=[a("https://www.ostechnix.com/know-command-program-will-exactly-executing/",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>[...s[11]||(s[11]=[a("SK",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),i(e,{href:"https://github.com/imquanquan"},{default:p(()=>[...s[12]||(s[12]=[a("imquanquan",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const w=l(h,[["render",u]]);export{x as __pageData,w as default};
